  static byte[] Response(string code,string last,string max,params byte[][] documents){XNamespace n=Rules.NfeNs,s="http://www.w3.org/2003/05/soap-envelope";var root=new XElement(n+"retDistDFeInt",new XAttribute("versao","1.01"),new XElement(n+"cStat",code),new XElement(n+"xMotivo","Resposta de teste"),new XElement(n+"ultNSU",Rules.Nsu(last)),new XElement(n+"maxNSU",Rules.Nsu(max)));var lot=new XElement(n+"loteDistDFeInt");foreach(byte[] doc in documents){byte[] zip;using(var m=new MemoryStream()){using(var g=new GZipStream(m,CompressionMode.Compress,true))g.Write(doc,0,doc.Length);zip=m.ToArray();}lot.Add(new XElement(n+"docZip",new XAttribute("NSU",Rules.Nsu(last)),new XAttribute("schema","procNFe_v4.00.xsd"),Convert.ToBase64String(zip)));}root.Add(lot);return Rules.Utf8(new XDocument(new XElement(s+"Envelope",new XElement(s+"Body",root))));}
