   string formatted=String.Join(" ",Enumerable.Range(0,11).Select(i=>k1.Substring(i*4,4)));Check(KeyPaste.Parse(formatted).Keys.Single()==k1,"chave com grupos separados por espaços");Check(KeyPaste.Parse("="+'"'+k1+'"').Keys.Single()==k1,"chave em fórmula textual de planilha");Check(KeyPaste.Parse("9"+k1+"1").Keys.Count==0,"não recorta números com mais de 44 posições");
   var dated=new List<DocItem>{new DocItem{Category="Recebidas",Date="2026-10-01T23:59:59-03:00",Key=k1,Partner="Fornecedor A",Number="1"},new DocItem{Category="Recebidas",Date="2026-10-12T00:00:00-03:00",Key=k2,Partner="Fornecedor B",Number="2"},new DocItem{Category="Recebidas",Date="2026-09-30T12:00:00-03:00",Key=Key(3),Partner="Fornecedor C"},new DocItem{Category="Recebidas",Date="",Key=Key(4)}};
   var from=new DateTime(2026,10,1);var to=new DateTime(2026,10,12);Check(DocumentFilter.Apply(dated,"Recebidas","",from,to).Count==2,"período inclusivo");Check(DocumentFilter.Apply(dated,"Recebidas","",from,from).Single().Key==k1,"data de emissão preserva fuso do XML");Check(DocumentFilter.Apply(dated,"Recebidas","Fornecedor B",from,to).Single().Key==k2,"período combinado com filtro textual");Check(DocumentFilter.Apply(dated,"Recebidas","",null,null).Count==4,"sem período inclui documentos sem data");Reject(()=>DocumentFilter.Apply(dated,"Recebidas","",to,from),"intervalo invertido");
   var qs=new KeyQueueStore(Path.Combine(root,"fila"));var q=new KeyQueue{Uf=35,AutoContinue=true};Check(q.Add(new[]{k1,k2,k1})==2,"deduplicação persistente da fila");qs.Save(SampleCnpj,1,q);Check(qs.Load(SampleCnpj,1).Jobs.Count==2,"fila persiste após reabrir");Check(qs.Load(SampleCnpj,2).Jobs.Count==0,"fila separada por ambiente");q.Jobs[0].Status="Consultando";qs.Save(SampleCnpj,1,q);Check(qs.Load(SampleCnpj,1).Jobs[0].Status=="Pendente","retoma consulta interrompida");using(qs.Lock(SampleCnpj,1))Reject(()=>{using(qs.Lock(SampleCnpj,1)){}},"duas execuções da mesma fila");
   var bs=new StateStore(Path.Combine(root,"batch-state"));var bq=new KeyQueueStore(Path.Combine(root,"batch-queue"));var bl=new XmlLibrary(Path.Combine(root,"batch-lib"),SampleCnpj,1);var many=new KeyQueue{Uf=35,AutoContinue=true};many.Add(Enumerable.Range(1,22).Select(i=>Key(i)));bq.Save(SampleCnpj,1,many);var bf=new Fake();for(int i=0;i<22;i++)bf.Replies.Enqueue(Response("137","0","0"));var br=new KeyBatchRunner(bs,bq,bl,bf,null);var first=br.Run(CancellationToken.None);Check(bf.Calls==20&&first.Pending==2,"lote pausa no limite de vinte chamadas");Check(first.Next>DateTime.UtcNow&&bq.Load(SampleCnpj,1).AutoContinue,"pendentes aguardam próxima janela");var again=br.Run(CancellationToken.None);Check(bf.Calls==20&&again.Pending==2,"reabrir não contorna limite");var st=bs.Load(SampleCnpj,1);st.KeyQueries=st.KeyQueries.Select(t=>t.AddHours(-2)).ToList();bs.Save(SampleCnpj,1,st);var last=br.Run(CancellationToken.None);Check(bf.Calls==22&&last.Pending==0,"continua restantes após liberar janela");Check(!bq.Load(SampleCnpj,1).AutoContinue,"desliga continuação ao terminar");Check(bs.Load(SampleCnpj,1).Last==Rules.Nsu("0"),"lote por chave não avança NSU sequencial");
   var skipQueue=new KeyQueue{Uf=35};skipQueue.Add(new[]{k1});var skipStore=new KeyQueueStore(Path.Combine(root,"skip-q"));skipStore.Save(SampleCnpj,1,skipQueue);bl.Store(Invoice(false),"1");var noCall=new Fake();new KeyBatchRunner(bs,skipStore,bl,noCall,null).Run(CancellationToken.None);Check(noCall.Calls==0&&skipStore.Load(SampleCnpj,1).Jobs[0].Status=="Já disponível","não gasta consulta com XML já salvo");
   var blockStates=new StateStore(Path.Combine(root,"block-state"));var blockQueues=new KeyQueueStore(Path.Combine(root,"block-queue"));var pending=new KeyQueue{Uf=35,AutoContinue=true};pending.Add(new[]{Key(30),Key(31)});blockQueues.Save(SampleCnpj,1,pending);var blocked=new Fake();blocked.Replies.Enqueue(Response("656","9","10"));var stop=new KeyBatchRunner(blockStates,blockQueues,bl,blocked,null).Run(CancellationToken.None);Check(blocked.Calls==1&&stop.Pending==2,"656 preserva todas as pendentes e interrompe lote");Check(blockStates.Load(SampleCnpj,1).Last==Rules.Nsu("0"),"656 por chave não altera NSU da distribuição");
   var errorStates=new StateStore(Path.Combine(root,"batch-error-state"));var errorQueues=new KeyQueueStore(Path.Combine(root,"batch-error-queue"));errorQueues.Save(SampleCnpj,1,pending);var failed=new Fake();new KeyBatchRunner(errorStates,errorQueues,bl,failed,null).Run(CancellationToken.None);Check(errorQueues.Load(SampleCnpj,1).Pending==2&&errorStates.Load(SampleCnpj,1).AllAfter>DateTime.UtcNow.AddMinutes(59),"erro de rede mantém fila e pausa consultas");
   var rejectStates=new StateStore(Path.Combine(root,"reject-state"));var rejectQueues=new KeyQueueStore(Path.Combine(root,"reject-queue"));rejectQueues.Save(SampleCnpj,1,pending);var rejectClient=new Fake();rejectClient.Replies.Enqueue(Response("641","0","0"));rejectClient.Replies.Enqueue(Response("137","0","0"));new KeyBatchRunner(rejectStates,rejectQueues,bl,rejectClient,null).Run(CancellationToken.None);Check(rejectQueues.Load(SampleCnpj,1).Jobs[0].Status=="Rejeitada"&&rejectClient.Calls==2,"rejeição de uma nota não perde demais chaves");
   using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();var stopped=new KeyBatchRunner(errorStates,errorQueues,bl,failed,null).Run(cancelled.Token);Check(stopped.Pending==2&&!errorQueues.Load(SampleCnpj,1).AutoContinue,"parar preserva fila e desliga retomada automática");}
   string xlsx=Path.Combine(root,"resultados.xlsx");QueueSpreadsheet.Save(xlsx,new[]{new KeyJob{Key=k1,Status="Pendente",Code="",Message="=HYPERLINK(\"exemplo\")"}});using(var stream=File.OpenRead(xlsx))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){Check(zip.GetEntry("[Content_Types].xml")!=null&&zip.GetEntry("xl/workbook.xml")!=null,"planilha possui partes obrigatórias");using(var sheet=zip.GetEntry("xl/worksheets/sheet1.xml").Open())using(var reader=new StreamReader(sheet)){var xml=XDocument.Parse(reader.ReadToEnd());XNamespace n="http://schemas.openxmlformats.org/spreadsheetml/2006/main";var keyCell=xml.Descendants(n+"c").Single(c=>(string)c.Attribute("r")=="A2");Check((string)keyCell.Attribute("t")=="inlineStr"&&keyCell.Descendants(n+"t").Single().Value==k1,"Excel recebe chave como texto íntegro");Check(!xml.Descendants(n+"f").Any(),"texto de resultado não vira fórmula na planilha");}}
  }
  static void LocalMutualTls(X509Certificate2 cert) {
   var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;
   bool authenticated=false,soap=false;var previous=ServicePointManager.ServerCertificateValidationCallback;
   // Only this offline self-test accepts its synthetic localhost certificate.
   ServicePointManager.ServerCertificateValidationCallback=delegate(object sender,X509Certificate remote,X509Chain chain,SslPolicyErrors errors){var request=sender as HttpWebRequest;return request!=null&&request.RequestUri.IsLoopback&&remote!=null&&remote.GetCertHashString()==cert.Thumbprint;};
   try {
    var server=Task.Run(delegate {using(var tcp=listener.AcceptTcpClient())using(var ssl=new SslStream(tcp.GetStream(),false,delegate(object sender,X509Certificate remote,X509Chain chain,SslPolicyErrors errors){return remote!=null&&remote.GetCertHashString()==cert.Thumbprint;})) {
     ssl.ReadTimeout=10000;ssl.WriteTimeout=10000;ssl.AuthenticateAsServer(cert,true,SslProtocols.Tls12,false);authenticated=ssl.IsMutuallyAuthenticated;
     var header=new StringBuilder();while(!header.ToString().EndsWith("\r\n\r\n")){int b=ssl.ReadByte();if(b<0||header.Length>16384)throw new IOException("Cabeçalho de teste inválido");header.Append((char)b);}
     if(header.ToString().IndexOf("100-continue",StringComparison.OrdinalIgnoreCase)>=0){byte[] interim=Encoding.ASCII.GetBytes("HTTP/1.1 100 Continue\r\n\r\n");ssl.Write(interim,0,interim.Length);ssl.Flush();}
     int length=int.Parse(System.Text.RegularExpressions.Regex.Match(header.ToString(),@"Content-Length:\s*(\d+)",System.Text.RegularExpressions.RegexOptions.IgnoreCase).Groups[1].Value);byte[] data=new byte[length];int at=0;while(at<length){int n=ssl.Read(data,at,length-at);if(n==0)throw new IOException("Pedido de teste truncado");at+=n;}
     XNamespace ns=Rules.NfeNs;soap=Rules.Xml(data).Descendants(ns+"distDFeInt").Count()==1&&header.ToString().Contains("application/soap+xml");
     byte[] reply=Response("137","0","0"),prefix=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/soap+xml; charset=utf-8\r\nContent-Length: "+reply.Length+"\r\nConnection: close\r\n\r\n");ssl.Write(prefix,0,prefix.Length);ssl.Write(reply,0,reply.Length);ssl.Flush();
    }});
    var method=typeof(SefazClient).GetMethod("Post",BindingFlags.NonPublic|BindingFlags.Instance);byte[] result=(byte[])method.Invoke(new SefazClient(cert),new object[]{"https://localhost:"+port+"/teste","teste",SefazClient.DistributionEnvelope(SampleCnpj,35,1,"0",null),CancellationToken.None});
    if(!server.Wait(15000))throw new IOException("Servidor local de teste não encerrou");Check(authenticated,"mTLS envia certificado A1 e prova chave privada");Check(soap&&DistributionResult.Parse(result).Code=="137","SOAP via HTTP com autenticação mútua");
   }finally{ServicePointManager.ServerCertificateValidationCallback=previous;listener.Stop();}
  }
  public static int Run(string[] args){string report=Path.Combine(System.Environment.GetFolderPath(System.Environment.SpecialFolder.UserProfile),"BuscaNFe-A1","testes.txt");Directory.CreateDirectory(Path.GetDirectoryName(report));string root=Path.Combine(Path.GetTempPath(),"XML-A1-Tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
   try {
    Check(Rules.Cnpj("11.222.333/0001-81")==SampleCnpj,"CNPJ numérico");Check(Rules.Cnpj("12.ABC.345/01DE-35")=="12ABC34501DE35","CNPJ alfanumérico");Reject(()=>Rules.Cnpj("11222333000180"),"DV inválido");Reject(()=>Rules.Cnpj("00000000000000"),"CNPJ zerado");Reject(()=>Rules.Cnpj("11222333000181<"),"CNPJ com símbolo");Check(Rules.Nsu("12")=="000000000000012","NSU preenchido");Reject(()=>Rules.Nsu("-1"),"NSU negativo");Reject(()=>Rules.Nsu("1000000000000000"),"NSU longo");Check(Rules.Key(Key()),"chave válida");Reject(()=>Rules.Xml(Encoding.UTF8.GetBytes("<!DOCTYPE x [<!ENTITY a SYSTEM 'file:///C:/Windows/win.ini'>]><x>&a;</x>")),"DTD / XXE");
    var envelope=Rules.Xml(SefazClient.DistributionEnvelope(SampleCnpj,35,1,"0",null));XNamespace n=Rules.NfeNs;Check(envelope.Descendants(n+"distDFeInt").Count()==1,"namespace do pedido");Check(envelope.Descendants(n+"CNPJ").Single().Value==SampleCnpj,"CNPJ do pedido");Check(envelope.Descendants(n+"ultNSU").Single().Value==Rules.Nsu("0"),"NSU do pedido");
    var lib=new XmlLibrary(Path.Combine(root,"biblioteca"),SampleCnpj,1);var incoming=lib.Store(Invoice(false),"1");Check(incoming.Category=="Recebidas","classificação recebidas");Check(File.ReadAllBytes(incoming.FilePath).SequenceEqual(Invoice(false)),"preservação dos bytes");Check(incoming.Amount==1250.90m,"valor da NF-e");Check(lib.Store(Invoice(true,2),"2",true).Category=="Emitidas","classificação emitidas");lib.Store(Invoice(false),"1");Check(lib.List().Count==2,"sem duplicação");Reject(()=>lib.Store(Summary(),"",true),"resumo não é XML completo");var hom=new XmlLibrary(Path.Combine(root,"hom"),SampleCnpj,2);Reject(()=>hom.Store(Invoice(false),"1",true),"ambiente diferente");
    var result=DistributionResult.Parse(Response("138","1","2",Invoice(false)));Check(result.Docs.Count==1,"descompactação de lote");Check(result.Docs[0].Bytes.SequenceEqual(Invoice(false)),"XML descompactado íntegro");
    DateTime now=DateTime.UtcNow;var cursor=new CursorState();cursor.Apply(result,false,now);Check(cursor.Last==Rules.Nsu("1"),"avanço NSU");Check(cursor.DistAfter<now,"continuação de lotes");cursor.Apply(DistributionResult.Parse(Response("138","2","2",Invoice(true,2))),false,now);Check(cursor.DistAfter==now.AddHours(1),"espera ao alcançar maxNSU");var limited=new CursorState();limited.Apply(DistributionResult.Parse(Response("137","0","0")),false,now);Check(limited.DistAfter==now.AddHours(1),"espera 137");limited.Apply(DistributionResult.Parse(Response("656","9","10")),false,now);Check(limited.Last==Rules.Nsu("9")&&limited.AllAfter==now.AddHours(1),"bloqueio 656 e alinhamento NSU");var point=new CursorState{Last=Rules.Nsu("5")};point.Apply(result,true,now);Check(point.Last==Rules.Nsu("5"),"consulta chave preserva cursor");
    var store=new StateStore(Path.Combine(root,"estado"));store.Save(SampleCnpj,1,cursor);var loaded=store.Load(SampleCnpj,1);Check(loaded.Last==cursor.Last&&loaded.DistAfter==cursor.DistAfter,"estado persiste");Check(!store.Load(SampleCnpj,2).Initialized,"ambientes separados");using(var held=store.Lock(SampleCnpj,1))Reject(()=>{using(var other=store.Lock(SampleCnpj,1)){}},"exclusão de execução concorrente");
    var runStore=new StateStore(Path.Combine(root,"run"));var runLib=new XmlLibrary(Path.Combine(root,"run-docs"),SampleCnpj,1);var fake=new Fake();fake.Replies.Enqueue(Response("138","1","2",Invoice(false)));fake.Replies.Enqueue(Response("138","2","2",Invoice(true,2)));var downloader=new Downloader(runStore,fake,runLib,null);Check(downloader.Run(35,"0",null,CancellationToken.None)==2,"fluxo completo com dois lotes");Check(fake.Ns.SequenceEqual(new[]{Rules.Nsu("0"),Rules.Nsu("1")}),"sequência exata NSU");Reject(()=>downloader.Run(35,"0",null,CancellationToken.None),"não consulta durante espera");Check(fake.Calls==2,"bloqueio impede chamada externa");
    var keyStore=new StateStore(Path.Combine(root,"keys"));var keyState=new CursorState{Last=Rules.Nsu("7"),Initialized=true};keyState.KeyQueries=Enumerable.Range(0,20).Select(i=>now.AddMinutes(-i)).ToList();keyStore.Save(SampleCnpj,1,keyState);var keyFake=new Fake();Reject(()=>new Downloader(keyStore,keyFake,runLib,null).Run(35,"0",Key(),CancellationToken.None),"limite vinte chaves");Check(keyFake.Calls==0,"não envia chave além do limite");
    var failStore=new StateStore(Path.Combine(root,"fail"));Reject(()=>new Downloader(failStore,new Fake(),runLib,null).Run(35,"0",null,CancellationToken.None),"falha de rede");Check(failStore.Load(SampleCnpj,1).AllAfter>DateTime.UtcNow.AddMinutes(59),"falha ambígua suspende repetição");
    string alphaKeyBase="35261012ABC34501DE3555001000000001100000001";int alphaSum=0,alphaWeight=2;for(int i=42;i>=0;i--){alphaSum+=(alphaKeyBase[i]-48)*alphaWeight;alphaWeight=alphaWeight==9?2:alphaWeight+1;}int alphaDv=11-alphaSum%11;Check(Rules.Key(alphaKeyBase+(alphaDv>=10?0:alphaDv).ToString()),"chave alfanumérica");
    var noAdvance=new CursorState();Reject(()=>noAdvance.Apply(DistributionResult.Parse(Response("138","0","2",Invoice(false))),false,now),"lote sem avanço");
    var inconsistent=new CursorState();Reject(()=>inconsistent.Apply(DistributionResult.Parse(Response("138","3","2",Invoice(false))),false,now),"NSU maior que máximo");
    var emptyStore=new StateStore(Path.Combine(root,"empty"));var emptyFake=new Fake();emptyFake.Replies.Enqueue(Response("138","1","1"));Reject(()=>new Downloader(emptyStore,emptyFake,runLib,null).Run(35,"0",null,CancellationToken.None),"lote 138 vazio");Check(emptyStore.Load(SampleCnpj,1).Last==Rules.Nsu("0"),"cursor não avança se lote inválido");
    TestPeriodAndBatch(root);TestScience(root);TestAutomaticDownloads(root);TestConfirmation(root);
    int certIndex=Array.IndexOf(args,"--test-cert");if(certIndex>=0){using(var cert=new CertificateSession(args[certIndex+1],"somente-teste")){Check(cert.Cnpj==SampleCnpj,"CNPJ extraído de SAN ICP-Brasil");cert.Validate(SampleCnpj);Reject(()=>cert.Validate("12345678000195"),"raiz de CNPJ diferente");Reject(()=>{using(var wrong=new CertificateSession(args[certIndex+1],"senha-incorreta")){}},"senha inválida do PFX");var signed=SefazClient.ScienceDocument(SampleCnpj,1,Key(),cert.Certificate);var signature=(XmlElement)signed.GetElementsByTagName("Signature",SignedXml.XmlDsigNamespaceUrl)[0];var checker=new SignedXml(signed);checker.LoadXml(signature);Check(checker.CheckSignature(cert.Certificate,true),"assinatura XML verificável");Check(signed.GetElementsByTagName("tpEvento",Rules.NfeNs)[0].InnerText=="210210","tipo do evento ciência");var soapSigned=new XmlDocument{PreserveWhitespace=true,XmlResolver=null};soapSigned.LoadXml(Encoding.UTF8.GetString(SefazClient.ScienceEnvelope(signed)));var soapChecker=new SignedXml(soapSigned);soapChecker.LoadXml((XmlElement)soapSigned.GetElementsByTagName("Signature",SignedXml.XmlDsigNamespaceUrl)[0]);Check(soapChecker.CheckSignature(cert.Certificate,true),"assinatura preservada no envelope SOAP");TestConfirmationSignature(cert.Certificate);}}
    if(certIndex>=0){using(var tlsCert=new CertificateSession(args[certIndex+1],"somente-teste"))LocalMutualTls(tlsCert.Certificate);}
    File.WriteAllText(report,"APROVADO: "+count+" verificações offline"+(certIndex>=0?", incluindo mTLS com servidor localhost e certificado sintético":" (sem etapa de certificado/mTLS)")+".\r\nDiretório dos testes: "+root+"\r\nNenhuma chamada à SEFAZ foi realizada.\r\n");return 0;
   }catch(Exception ex){File.WriteAllText(report,"FALHA após "+count+" verificações:\r\n"+ex+"\r\nDiretório: "+root);return 1;}
  }
